<?php
require_once __DIR__.'/includes/functions.php';must_login();require_permission('reports');require_once __DIR__.'/config/database.php';$desde=$_GET['desde']??date('Y-m-01');$hasta=$_GET['hasta']??date('Y-m-d');if(!valid_date($desde)||!valid_date($hasta)||$desde>$hasta){$desde=date('Y-m-01');$hasta=date('Y-m-d');}$st=$pdo->prepare('SELECT COALESCE(SUM(monto),0) FROM pagos WHERE estado="Pagado" AND DATE(fecha_pago) BETWEEN ? AND ?');$st->execute([$desde,$hasta]);$ingresos=(float)$st->fetchColumn();$st=$pdo->prepare('SELECT COUNT(*) FROM citas WHERE fecha BETWEEN ? AND ?');$st->execute([$desde,$hasta]);$total=(int)$st->fetchColumn();$st=$pdo->prepare('SELECT estado,COUNT(*) total FROM citas WHERE fecha BETWEEN ? AND ? GROUP BY estado');$st->execute([$desde,$hasta]);$states=$st->fetchAll();$st=$pdo->prepare("SELECT s.nombre,COUNT(*) total FROM citas c JOIN servicios s ON s.id=c.servicio_id WHERE c.fecha BETWEEN ? AND ? AND c.estado NOT IN ('Cancelada','No asistió') GROUP BY s.id ORDER BY total DESC LIMIT 10");$st->execute([$desde,$hasta]);$popular=$st->fetchAll();$st=$pdo->prepare('SELECT DATE(fecha_pago) dia,SUM(monto) total FROM pagos WHERE estado="Pagado" AND DATE(fecha_pago) BETWEEN ? AND ? GROUP BY DATE(fecha_pago) ORDER BY dia');$st->execute([$desde,$hasta]);$daily=$st->fetchAll();$title='Reportes';require __DIR__.'/includes/header.php';?>
<div class="heading"><div><span class="eyebrow">ANÁLISIS DEL NEGOCIO</span><h1>Reportes</h1><p class="muted">Consulta los resultados por periodo.</p></div></div><section class="panel"><form class="filters" method="get"><label class="field"><span>Desde</span><input type="date" name="desde" value="<?=e($desde)?>"></label><label class="field"><span>Hasta</span><input type="date" name="hasta" value="<?=e($hasta)?>"></label><button class="btn">Filtrar</button><button type="button" class="btn ghost" onclick="window.print()">Imprimir</button></form></section><div class="stats"><div class="stat"><small>Ingresos pagados</small><b><?=money($ingresos)?></b></div><div class="stat"><small>Citas registradas</small><b><?=$total?></b></div><div class="stat"><small>Servicios con demanda</small><b><?=count($popular)?></b></div></div><div class="split"><section class="panel"><h2>Servicios más solicitados</h2><div class="tablewrap"><table><tr><th>Servicio</th><th>Citas</th></tr><?php foreach($popular as $p):?><tr><td><?=e($p['nombre'])?></td><td><?=$p['total']?></td></tr><?php endforeach;?></table></div></section><section class="panel"><h2>Estado de citas</h2><div class="tablewrap"><table><tr><th>Estado</th><th>Cantidad</th></tr><?php foreach($states as $s):?><tr><td><?=e($s['estado'])?></td><td><?=$s['total']?></td></tr><?php endforeach;?></table></div></section></div><section class="panel"><h2>Ingresos por día</h2><div class="tablewrap"><table><tr><th>Fecha</th><th>Ingresos</th></tr><?php foreach($daily as $d):?><tr><td><?=e($d['dia'])?></td><td><?=money($d['total'])?></td></tr><?php endforeach;?></table></div></section><?php require __DIR__.'/includes/footer.php';?>
